import os
import csv
from openpyxl import load_workbook

def task_func(file_name, excel_file_path, csv_file_path) -> str:
    excel_full_path = os.path.join(excel_file_path, file_name)
    base_name, ext = os.path.splitext(file_name)
    csv_file_name = base_name + ".csv"
    csv_full_path = os.path.join(csv_file_path, csv_file_name)

    if csv_file_path:
        os.makedirs(csv_file_path, exist_ok=True)

    with open(csv_full_path, "w", newline="", encoding="utf-8") as csv_file:
        writer = csv.writer(csv_file)

        if ext.lower() == ".xls":
            import xlrd

            workbook = xlrd.open_workbook(excel_full_path)
            sheet = workbook.sheet_by_index(0)

            for row_idx in range(sheet.nrows):
                row = []
                for cell in sheet.row(row_idx):
                    if cell.ctype == xlrd.XL_CELL_EMPTY:
                        row.append("")
                    elif cell.ctype == xlrd.XL_CELL_DATE:
                        row.append(xlrd.xldate_as_datetime(cell.value, workbook.datemode))
                    else:
                        row.append(cell.value)
                writer.writerow(row)
        else:
            workbook = load_workbook(excel_full_path, data_only=True)
            sheet = workbook.active

            for row in sheet.iter_rows(values_only=True):
                writer.writerow(["" if cell is None else cell for cell in row])

            workbook.close()

    return csv_file_name
